 byte[] main=File.ReadAllBytes(Path.Combine(work,"state.dat")),backup=File.ReadAllBytes(Path.Combine(work,"state.dat.bak"));before=FullStateRestorePlan.Fingerprint(target);original=target.Profiles;bool flushed=false;store=Open(work,p=>{if(p=="state-flushed")flushed=true;});plan=FullStateRestorePlan.Prepare(target,State("denied"));bool denied=false;using(var held=new FileStream(Path.Combine(work,"state.dat"),FileMode.Open,FileAccess.Read,FileShare.Read)){try{plan.Apply(target,()=>true,s=>Call(store,"Save",s));}catch(IOException){denied=true;}}
 Check(denied&&flushed,"Real replacement sharing failure occurs after encrypted candidate flush");Check(before==FullStateRestorePlan.Fingerprint(target)&&ReferenceEquals(original,target.Profiles),"Real file failure preserves live state");Check(main.SequenceEqual(File.ReadAllBytes(Path.Combine(work,"state.dat")))&&backup.SequenceEqual(File.ReadAllBytes(Path.Combine(work,"state.dat.bak"))),"Real file failure preserves primary and backup bytes");Check(Directory.GetFiles(work,"state.dat.next-*").Length==0,"Failed candidate cleaned");
 identityPlan=FullStateRestorePlan.PrepareIdentitiesOnly(target,identityTarget.SubscriptionIdentities);identityPlan.Apply(target,()=>true,s=>Call(Open(work),"Save",s));Check(FullStateRestorePlan.Fingerprint(target)==FullStateRestorePlan.Fingerprint((AppState)Call(Open(work),"Load")),"Actual DPAPI identity-only commit equals live model"); main=File.ReadAllBytes(Path.Combine(work,"state.dat"));backup=File.ReadAllBytes(Path.Combine(work,"state.dat.bak"));before=FullStateRestorePlan.Fingerprint(target);identityRef=target.SubscriptionIdentities;flushed=false;store=Open(work,p=>{if(p=="state-flushed")flushed=true;});identityPlan=FullStateRestorePlan.PrepareIdentitiesOnly(target,new IdentityState());denied=false;
 using(var held=new FileStream(Path.Combine(work,"state.dat"),FileMode.Open,FileAccess.Read,FileShare.Read)){try{identityPlan.Apply(target,()=>true,s=>Call(store,"Save",s));}catch(IOException){denied=true;}}
